use super::*;

/// Is `pane_id` one of the app-owned studio sessions?
///
/// Membership OR the studio pane GRAMMAR, since `the-studio-session-set-is-derived-not-declared`.
///
/// Membership alone was correct only while every studio pane id existed at compile time. The
/// per-technology studios are DERIVED now — a librarian exists because the algorithms graph holds its
/// technology — so a list can lag reality, and the direction it lags in is the dangerous one: an
/// unrecognised pane is offered to the user by the recovery banner as a restorable fleet worker, and
/// reaches the launch with no role gate. `bsc_session::is_studio_pane_id` recognises the SHAPE
/// (`algorithms-studio:librarian-<tech>`), which is true whether or not anything has read the axis.
///
/// The passed list is still consulted and still matters. It is what carries the ids the grammar does
/// NOT describe — above all `debug-studio:debugger`, which is in the registry while
/// `debug-studio:req-4212` shares its prefix and must not match. That distinction is a MEMBERSHIP one
/// and the reason this was never a prefix test; see the module docs for what it cost. Keeping the
/// parameter is also what lets the fixture drive the empty-registry case.
pub fn is_studio_session_pane_id(pane_id: &str, studio_pane_ids: &[String]) -> bool {
    studio_pane_ids.iter().any(|id| id == pane_id) || bsc_session::is_studio_pane_id(pane_id)
}
